import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"57、【巽】 巽下巽上","description":"周易集注 - 57、【巽】 巽下巽上","frontmatter":{"title":"57、【巽】 巽下巽上","description":"周易集注 - 57、【巽】 巽下巽上"},"headers":[],"relativePath":"zh/classics/jizhu/061.md","filePath":"zh/classics/jizhu/061.md"}'),h={name:"zh/classics/jizhu/061.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_57、【巽】-巽下巽上" tabindex="-1">57、【巽】 巽下巽上 <a class="header-anchor" href="#_57、【巽】-巽下巽上" aria-label="Permalink to “57、【巽】 巽下巽上”">​</a></h1><p>巽入也，二阴伏于四阳之下，能巽顺乎阳，故名为巽。其象为风，风亦取入义，亦巽之义也。《序卦》：旅而无所容，故受之以巽。旅途亲寡，非巽顺何以取容?所以次旅。</p><p>小亨者，以卦本属阴，又卑巽也，惟其如是，则才智不足以识远任重，仅可小亨。虽小亨，然利有所往，盖巽以从人，人无不悦，所以利有攸往。然使失其所从，未必利往。纵使利往，失其正矣，故利见大德之人。此则因其从阳，而教之以所从之人也。</p><p>《彖》曰：重巽以申命，刚巽乎中正，而志行，柔皆顺乎刚，是以小亨，利有攸往，利见大人。</p><p>释卦义，又以卦体释卦辞。重巽者，上下皆巽也。申命者，丁宁重复也，非两番降命也。风之吹物，无处不入，无物不鼓动。诏令之入人，亦如风之动物也。〔陆贽从狩俸天所下制书，日以百计，虽勇夫悍卒，无不感动流涕，则申命之系于人君亦大矣。〕刚巽乎中正，指九五，巽乎中正者，居巽卦之中正也。志行者，能行其志也，盖刚居中正，则所行当其理，而无过中失正之弊。凡出身加民，皆建中表正，而志以行矣，此大人之象也。柔指初与四，刚指二三五六，惟柔能顺乎刚，是以小亨。利有攸往，惟刚巽乎中正，故利见大人。</p><h3 id="《象》曰-随风巽-君子以申命行事。" tabindex="-1">《象》曰：随风巽，君子以申命行事。 <a class="header-anchor" href="#《象》曰-随风巽-君子以申命行事。" aria-label="Permalink to “《象》曰：随风巽，君子以申命行事。”">​</a></h3><p>前风去而后风随之，故曰随风。申命者，随风之象也。申命者，所以晓谕于行事之先，行事者所以践言于申命之后，其实一事也。〔商之盘庚，周之洛诰，谆谆于言语之间者，欲民晓知君上之心事，所以申命行事也。故建中之诏，虽不及商周，而随时救弊，亦未必无小补云。〕</p><p>初六，进退，利武人之贞。</p><p>巽为进退，进退之象也。变干纯刚，故曰武人。故履六三变干亦曰武人，皆阴居阳位，变阳则称武人也。盖阴居阳位则不正，变干则贞矣，故曰利武人之贞。曰利武人之贞，如云利阳刚之正也。</p><p>初六阴柔居下，又为巽之主，乃卑巽之过者也，是以持狐疑之心。凡事是非可否，莫之适从，故有进退之象。若此者，以刚果之不足也。茍能如武人之贞，则有以矫其柔懦之偏，不至于过巽矣。故教占者如是。</p><h3 id="《象》曰-进退-志疑也。利武人之贞-志治也。" tabindex="-1">《象》曰：进退，志疑也。利武人之贞，志治也。 <a class="header-anchor" href="#《象》曰-进退-志疑也。利武人之贞-志治也。" aria-label="Permalink to “《象》曰：进退，志疑也。利武人之贞，志治也。”">​</a></h3><p>进退者，以阴柔居巽下，是非可否，莫之适从，志疑故也。惟疑则方寸已乱，不能决进退矣。若柔而济之以刚，则心之所之者有定见，事之所行者有定守，可进则决于进，可退则决于退，不持疑于两可，治而不乱矣。</p><p>九二，巽在床下，用史巫纷若，吉，无咎。</p><p>一阴在下，二阳在上，床之象，故剥以床言。巽性伏，二无应于上，退而比初，心在于下，故曰床下。中爻为兑，又巽综兑，兑为巫，史巫之象也。又为口舌，为毁、为附，纷若之象也。史掌卜筮，曰史巫者，善于卜吉凶之巫也，故曰史巫，非两人也。〔《周礼》“女巫有府一人，史四人，胥四人”，《离骚》云“巫咸将夕降兮，怀椒糈而要之”注，“巫咸，古之神巫，善于筮吉凶者”。〕纷者缤纷杂乱貌，若语助辞。〔巫者，男曰觋，女曰巫，巽为少女，故以巫言之。〕初乃阴爻，居于阳位，二乃阳爻，居于阴位，均之过于卑巽者也。初教以武人之贞，教之以直前勇敢也。二教之以巫之纷若，教之以抖擞奋发也。初阴据阳位，故教以男子之武，二阳据阴位，故教以女人之纷，爻辞之精如此。</p><p>二以阳处阴，而居下无应，乃比乎初，故有巽在床下之象。然居下体，亦过于卑巽者，必不自安宁，如史巫之纷若，鼓舞动作，则有以矫其柔懦之偏，不惟得其吉，而在我亦无过咎矣。教占者当如是也。</p><h3 id="《象》曰-纷若之吉-得中也。" tabindex="-1">《象》曰：纷若之吉，得中也。 <a class="header-anchor" href="#《象》曰-纷若之吉-得中也。" aria-label="Permalink to “《象》曰：纷若之吉，得中也。”">​</a></h3><p>得中者，得中而不过于卑巽也。凡小象，二五言中字，皆因中位，又兼人事。</p><p>九三，频巽吝。</p><p>频者数也，三居两巽之间，一巽既尽，一巽复来，频巽之象。曰频巽，则频失可知矣。频巽与频复不同，频复者终于能复也，频巽者终于不巽也。</p><p>九三过刚不中，又居下体之上，本不能巽，但当巽之时，不容不巽矣。然屡巽屡失，吝之道也。故其象占如此。</p><h3 id="《象》曰-频巽之吝-志穷也。" tabindex="-1">《象》曰：频巽之吝，志穷也。 <a class="header-anchor" href="#《象》曰-频巽之吝-志穷也。" aria-label="Permalink to “《象》曰：频巽之吝，志穷也。”">​</a></h3><p>三本刚，而位又刚，已不能巽矣，又乘刚，安能巽。曰志穷者，言心虽欲巽，而不得巽也。</p><p>六四，悔亡，田获三品。</p><p>中爻离，为戈兵，巽错震，戈兵震动，田之象也。离居三，三品之象也。三品者，初巽为鸡，二兑为羊，三离为雉也。</p><p>六四当巽之时，阴柔无应，承乘皆刚，宜有悔矣。然以阴居阴，得巽之正，又居上体之下，盖居上而能下者也。故不惟悔亡，而且有田获三品之象。占者能如是，则所求必得而有功矣。</p><h3 id="《象》曰-田获三品-有功也。" tabindex="-1">《象》曰：田获三品，有功也。 <a class="header-anchor" href="#《象》曰-田获三品-有功也。" aria-label="Permalink to “《象》曰：田获三品，有功也。”">​</a></h3><p>八卦正位，巽在四，所以获三品而有功。</p><p>九五，贞吉，悔亡，无不利，无初有终。先庚三日，后庚三日，吉。</p><p>先庚后庚，详见蛊卦。五变则外卦为艮，成蛊矣。先庚丁，后庚癸，其说始于郑玄，不成其说。</p><p>九五居尊，为巽之主，命令之所由出者也。以其刚健中正，故正而又吉，然巽顺之体，初时不免有悔，至此则悔亡而无不利矣。惟其悔亡而无不利，故无初有终也。然命令之出，所系匪轻，必原其所以始，虑其所以终，先庚三日，后庚三日，庶乎命令之出，如风之吹物，无处不入，无物不鼓动矣。占者必如是而吉也。</p><h3 id="《象》曰-九五之吉-位正中也。" tabindex="-1">《象》曰：九五之吉，位正中也。 <a class="header-anchor" href="#《象》曰-九五之吉-位正中也。" aria-label="Permalink to “《象》曰：九五之吉，位正中也。”">​</a></h3><p>刚健中正，未有不吉者。曰悔亡者，巽累之也。故孔子止言九五之吉。</p><p>上九，巽在床下，丧其资斧，贞凶。</p><p>本卦巽木综兑金，又中爻兑金，斧之象也。又中爻离为戈兵，亦斧之象也。阴乃巽之主，阴在下四爻，上亦欲比乎四，故与二之巽在床下同。九三九五不言床下者，三过刚，五居中得正也。巽近市利三倍，本有其资，此爻变坎为盗，则丧其资矣。且中爻离兑斧象，皆在下爻，不相管摄，是丧其斧矣。贞者，巽本美德也。</p><p>上九居巽之终，而阴居于下，当巽之时，故亦有巽在床下之象。但不中不正，穷之极矣，故又有丧其资斧之象。占者得此，虽正亦凶也。</p><h3 id="《象》曰-巽在床下-上穷也。丧其资斧-正乎凶也。" tabindex="-1">《象》曰：巽在床下，上穷也。丧其资斧，正乎凶也。 <a class="header-anchor" href="#《象》曰-巽在床下-上穷也。丧其资斧-正乎凶也。" aria-label="Permalink to “《象》曰：巽在床下，上穷也。丧其资斧，正乎凶也。”">​</a></h3><p>上穷者，言上九之时势也，非释巽在床下也。巽在床下，乃本卦之事，当巽之时，不容不巽者也。正乎凶，即爻辞贞凶。</p>',37)])])}const m=e(h,[["render",t]]);export{_ as __pageData,m as default};
